#!/usr/bin/env bash
# ModSync's Play hook for @@GAME_NAME@@ in Heroic (GOG @@APP_NAME@@).
# Generated by ModSync @@MODSYNC_VERSION@@ (hook version @@HOOK_VERSION@@) — do not
# edit; ModSync rewrites it, and `@@DISABLE_COMMAND@@` takes it out of the
# game's settings in Heroic.
#
# Heroic puts its wrappers ahead of the game's command line, so this gets
# ModSync's marker arguments, then whatever runs the game (umu-run, and any
# wrappers after this one) and the game's program with its arguments. It keeps
# the first part and runs Mod Organizer 2 in place of the program: the game is
# still Heroic's launch, so Heroic tracks it and syncs GOG cloud saves as usual.
# The program is the first .exe inside the game's folder; a launch without one
# runs as it was. Heroic's Flatpak can't start ModSync or read ModSync's
# settings, so what this needs is written in below, and MO2's executable for
# the game is read from MO2's own settings on every launch.
#
# Every launch sets WINEDLLOVERRIDES for winmm and version (native, then Wine's
# own): Cyber Engine Tweaks and RED4ext load through those DLLs. MO2-LINT's
# "Launch Mod Organizer" option opens MO2 instead of playing. A launch ModSync
# asked Heroic for leaves a note in $launch_note, which this takes (once, and
# only while fresh): an nxm:// link opens MO2 with it, and ModSync's Play and
# Open MO2 play or open MO2 whichever launch option Heroic ran.
# MODSYNC_ORIGINAL_GAME=1 in the game's environment variables in Heroic starts
# the game as Heroic would have.
set -u

instance=@@INSTANCE@@
game_dir=@@GAME_DIR@@
game_exe=@@GAME_EXE@@             # MO2 executables running this play the game
prefer=@@PREFER_ARGUMENT@@        # and the one with this argument wins
direct=(@@DIRECT_ARGS@@)          # MO2's arguments when it has no such executable yet
launch_note=@@LAUNCH_NOTE@@
launch_taken=@@LAUNCH_TAKEN@@  # emptied once taken: its time is when MO2's launch began
note_ttl=@@NOTE_TTL@@     # seconds

say() { printf 'ModSync: %s\n' "$*" >&2; }  # Heroic keeps it in the game's log

# A Windows path (Z:\home\…) as the Linux one it stands for.
unix_path() {
    local p="${1//\\//}"
    [[ "${p,,}" == z:/* ]] && p="${p:2}"
    printf '%s' "$p"
}

[[ "${1-}" == "@@MARKER@@" ]] && shift 2

merged=""
IFS=';' read -r -a entries <<< "${WINEDLLOVERRIDES-}"
for entry in "${entries[@]}"; do
    dlls="${entry%%=*}"
    mode=""
    [[ "$entry" == *=* ]] && mode="=${entry#*=}"
    kept=""
    IFS=',' read -r -a names <<< "$dlls"
    for name in "${names[@]}"; do
        trimmed="${name//[[:space:]]/}"
        case "${trimmed,,}" in ""|winmm|version) continue ;; esac
        kept+="${kept:+,}$name"
    done
    [[ -n "$kept" ]] && merged+="${merged:+;}$kept$mode"
done
export WINEDLLOVERRIDES="${merged:+$merged;}winmm,version=n,b"

# The note is for this launch, whatever it turns out to be: taken first, so
# one this launch doesn't use can't turn a later Play into something else.
download="" request="" taken=""
if [[ -f "$launch_note" ]] && mv -f "$launch_note" "$launch_taken" 2>/dev/null; then  # taken whole, once
    taken=1
    left=$(stat -c %Y "$launch_taken" 2>/dev/null || echo 0)
    note=""
    IFS= read -r note < "$launch_taken" || true
    : > "$launch_taken"
    if (( $(date +%s) - left > note_ttl )); then
        say "ignoring a note ModSync left over ${note_ttl}s ago"
    elif [[ "${note,,}" == nxm://* ]]; then
        download=$note
    elif [[ "$note" == "@@PLAY@@" || "$note" == "@@OPEN@@" ]]; then
        request=$note
    else
        say "ignoring a note ModSync left that this doesn't know: $note"
    fi
fi

# Running the launch as it was. MO2 isn't coming, so ModSync mustn't wait for it.
as_it_was() {
    say "$1"
    [[ -n "$download$request" ]] && say "what ModSync asked this launch for ($request${download:+a Nexus download}) is dropped"
    [[ -n "$taken" ]] && rm -f "$launch_taken"
    exec "${launch[@]}"
}

launch=("$@")
target=-1
for i in "${!launch[@]}"; do
    p=$(unix_path "${launch[$i]}")
    if [[ "${p,,}" == *.exe && "$p" == "$game_dir"/* ]]; then
        target=$i
        break
    fi
done
(( target >= 0 )) || as_it_was "no program from $game_dir in the launch; running it as it was"
[[ -z "${MODSYNC_ORIGINAL_GAME:-}" ]] ||
    as_it_was "MODSYNC_ORIGINAL_GAME is set; starting the game without Mod Organizer 2"
[[ -f "$instance/ModOrganizer.exe" ]] || as_it_was \
    "WARNING: $instance/ModOrganizer.exe isn't there (or Heroic can't see it); starting the game without Mod Organizer 2"
runner=("${launch[@]:0:target}")
program=$(unix_path "${launch[$target]}")
program="${program##*/}"

if [[ -n "$download" ]]; then
    args=("$download")
    say "opening Mod Organizer 2 ($instance) for a Nexus Mods download"
elif [[ "$request" == "@@OPEN@@" || ( -z "$request" && "${program,,}" == "mo2-redirector.exe" ) ]]; then
    args=()
    say "opening Mod Organizer 2 ($instance)"
else
    # MO2's executables, as its settings list them: N\title, N\binary, N\arguments.
    titles=() binaries=() arguments=()
    section=""
    while IFS= read -r line || [[ -n "$line" ]]; do
        line="${line%$'\r'}"
        if [[ "$line" == \[*\] ]]; then
            section="${line:1:${#line}-2}"
            continue
        fi
        [[ "$section" == customExecutables && "$line" =~ ^([0-9]+)\\(title|binary|arguments)=(.*)$ ]] || continue
        n="${BASH_REMATCH[1]}" value="${BASH_REMATCH[3]}"
        [[ "$value" == \"*\" ]] && value="${value:1:${#value}-2}"
        case "${BASH_REMATCH[2]}" in
            title) titles[n]="$value" ;;
            binary) binaries[n]="$value" ;;
            arguments) arguments[n]="$value" ;;
        esac
    done < "$instance/ModOrganizer.ini"
    chosen="" fallback=""
    for n in "${!binaries[@]}"; do
        b=$(unix_path "${binaries[n]}")
        [[ "${b,,}" == */"${game_exe,,}" && -n "${titles[n]-}" ]] || continue
        [[ -z "$fallback" ]] && fallback="${titles[n]}"
        if [[ -z "$chosen" && " ${arguments[n]-} " == *" $prefer "* ]]; then
            chosen="${titles[n]}"
        fi
    done
    chosen="${chosen:-$fallback}"
    if [[ -n "$chosen" ]]; then
        args=(run -e "$chosen")
    else
        args=("${direct[@]}")
    fi
    say "playing through Mod Organizer 2 ($instance) in place of $program: ${args[*]}"
fi
cd "$instance" || exit 1
exec "${runner[@]}" "$instance/ModOrganizer.exe" "${args[@]}"
